229	// Converge every wiring surface, returning a flat summary of what changed (empty
230	// when the repo was already converged). `stubText` is the vendored scheduler stub.
231	//
232	// `badges` defaults off, and that default is the point: the nightly takes this
233	// call as it stands and only bootstrap opts the README row in.
234	// `workflows: false` converges everything EXCEPT `.github/workflows/`. The engine
235	// update flow passes it: the scheduler workflow's content is a function of the
236	// task set, so pack changes are what rewrite it, and only the pack flow carries a
237	// credential that can land a workflow file at all (DESIGN §2.4, §3.7). A flow that
238	// wrote one it cannot deliver would fail its whole push, not just that file.
239	export async function convergeWiring(root, fullName, stubText, secretNames = [], { badges = false, workflows = true } = {}) {
240	  const changed = [];
241	  if (workflows && convergeSchedulerWorkflow(root, fullName, stubText, secretNames)) changed.push(SCHEDULER_WORKFLOW);
242	  const hooks = ensureHooks(root);
