244	  if (removeRetiredCorpusImport(root)) changed.push(`removed retired ${CLAUDE_MD} corpus import`);
245	  if (removeRetiredBadgeSetting(root)) changed.push('removed retired badges setting');
246	  if (badges && convergeBadgeRow(root, await badgeRowEntries(root, await repoConfig(root)))) changed.push(`${README} pack row`);
247	  return { changed, ...(hooks.error ? { error: hooks.error } : {}) };
