258	  const badges = argv.includes('--badges');
259	  const fullName = argv.find((a) => !a.startsWith('--')) || process.env.GITHUB_REPOSITORY || process.env.CLAUDINITE_REPO;
260	  if (!fullName) { console.error('converge-wiring: need owner/repo (argv or GITHUB_REPOSITORY)'); process.exit(1); }
261	  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
262	  const stubPath = join(root, '.claudinite/shared/engine/scheduler/stubs/claudinite-scheduler.yml');
263	  if (!existsSync(stubPath)) { console.error(`converge-wiring: vendored stub not found at ${stubPath}`); process.exit(1); }
264	  const secretNames = await declaredSecrets(root, await repoConfig(root));
265	  const { changed, error } = await convergeWiring(root, fullName, readFileSync(stubPath, 'utf8'), secretNames, { badges });
266	  if (error) console.log(`! ${error}`);
267	  console.log(changed.length ? `converge-wiring: ${changed.join(', ')}` : 'converge-wiring: already converged');
268	}
269	
270	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) main();
