94	// A per-cycle maintenance branch name — dated + a short seed so each cycle gets a
95	// distinct branch (superseding #407's scheme, native-git side). `seed` is passed
96	// in so this is pure; main() generates it.
97	export function maintenanceBranchName(dateStr, seed) {
98	  return `${MAINT_PREFIX}-${dateStr}-${seed}`;
99	}
100	
101	// The family's open maintenance PR, found by head-branch PREFIX (the name carries
102	// a per-cycle seed, so the prefix is what identifies the family): the cycle
103	// DISPOSES of this one — merge or close — before cutting its own, which is what
104	// keeps them from piling up night-over-night. null → nothing to dispose of. The
105	// whole PR is returned, not just its ref, because disposal needs its number and
106	// head sha.
107	export function openMaintenancePull(pulls, prefix = MAINT_PREFIX) {
108	  return (pulls ?? []).find((pr) => String(pr?.head?.ref ?? '').startsWith(prefix)) ?? null;
109	}
110	
111	// Its head branch alone — the shape most callers want.
112	export function openMaintenanceBranch(pulls, prefix = MAINT_PREFIX) {
113	  return openMaintenancePull(pulls, prefix)?.head?.ref ?? null;
114	}
