133	// The escalation decision (owner, 2026-07-23): agent iff a pending agentic note,
134	// or a real change the deterministic converge left non-green. No change, or a
135	// green change with no agentic note, stays agentless.
136	//
137	// It returns the REASON, not a bit — `null` for an agentless night, otherwise
138	// `{ code, detail }`. The worker knew which of four conditions fired and then threw
139	// it away; the agent it woke re-derived all four from scratch, and on
140	// EdFringeAllocator#82 re-derived them WRONG (it reported "preprocessing created
141	// nothing" about a cycle that had merged its PR a second earlier) and closed a
142	// six-minute run as a no-op. `code` is the stable identifier a consumer branches on;
143	// `detail` is the sentence a human reads in the dispatch issue.
144	//
145	// It names the CONDITION and its counts, never the findings themselves — those stay
146	// in the repo for the agent to re-run (DESIGN §3, the no-code→agent-data-channel rule;
147	// the named exception is identity, not content).
148	//
149	// The branch ORDER is the escalation precedence, most-specific first: a night with a
150	// pending note and a red check is a note night, because the note is what the agent
151	// must apply and the red check may well be the note's own doing.
152	export function escalation({
153	  pendingCount, meaningfulChange, checksPass, selftestOk = true, withheldCount = 0,
154	  checksCrashed = false, selftestCrashed = false,
155	}) {
156	  if (pendingCount > 0) {
157	    return { code: 'agentic-notes', detail: `${pendingCount} pending agentic migration note(s) to apply` };
158	  }
159	  // A withheld workflow file is work this stage COULD not do, not work it chose to
160	  // leave: without the agent, the file simply never lands, and the converge would
161	  // report itself clean while the repo stays un-updated.
162	  if (withheldCount > 0) {
163	    return {
164	      code: 'withheld-workflows',
165	      detail: `${withheldCount} workflow file(s) the Action token cannot push — only the agent's credential can land them`,
166	    };
167	  }
168	  // A converged mount that cannot pass its own self-test is the judgment case
169	  // whether or not the converge "changed" anything a diff can see: broken
170	  // machinery reports no findings precisely because it is not running.
171	  if (!selftestOk) {
172	    return selftestCrashed
173	      ? { code: 'selftest-could-not-run', detail: 'the converged mount\'s self-test could not run at all — machinery, not content' }
174	      : { code: 'selftest-failed', detail: 'the converged mount FAILED its self-test — the machinery that runs the rules is not intact' };
175	  }
176	  if (Boolean(meaningfulChange) && !checksPass) {
177	    return checksCrashed
178	      ? { code: 'checks-could-not-run', detail: 'check_the_world could not run on the converged tree — no verdict was produced' }
179	      : { code: 'checks-not-green', detail: 'check_the_world reported findings on the converged tree that the deterministic pass could not fix' };
180	  }
181	  return null;
182	}
