195	// --- I/O shell (validated by the live pilot, not unit tests) ----------------
196	
197	const git = (args, opts = {}) =>
198	  execFileSync('git', args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], ...opts });
199	// `opts` exists for ONE reason: `cwd`. This worker's own cwd is the task dir INSIDE the
200	// mount (prework.mjs spawns it there), and step 2 deletes that whole tree before
201	// re-copying it — so from the vendor step onward this process is running in an unlinked
202	// directory, and every child it spawns inherits it. A child that calls `process.cwd()`
203	// dies with `ENOENT … uv_cwd` (#689). Children are therefore pointed at the repo root,
204	// which is the directory they were always meant to be working in.
205	const node = (args, extraEnv = {}, opts = {}) =>
206	  execFileSync(process.execPath, args, {
207	    encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], env: { ...process.env, ...extraEnv }, ...opts,
208	  });
