261	// REHEARSAL MODE (per-project-scheduling rehearsal, #593 phase 0). A run may be
262	// pointed at a canon BRANCH instead of its default head, so a canon change can be
263	// tried against a real repo before it merges. `CLAUDINITE_CANON_REF` selects the
264	// ref; `CLAUDINITE_CANON_URL` a fork.
265	//
266	// The stamp is the whole reason this needs its own decision rather than an extra
267	// clone argument. A branch head is NOT on trunk, and stamping it is precisely the
268	// shape vendoring's #328 anti-rewind guard refuses to write over afterwards
269	// (`ref-not-on-trunk`, which the sheepdog freshness sweep reads as WEDGED, not
270	// late) — a rehearsal would leave the repo unable to baseline ever again. This
271	// was not hypothetical: it happened by hand on 2026-07-30, to all thirteen
272	// members at once, from a converge run out of an unmerged branch.
273	//
274	// So a rehearsal stamps NOTHING. It converges, it reports, and it leaves the
275	// member's provenance exactly as it found it.
276	export function canonSource(env = {}) {
277	  const ref = String(env.CLAUDINITE_CANON_REF ?? '').trim();
278	  const url = String(env.CLAUDINITE_CANON_URL ?? '').trim() || CANON_URL;
279	  return { url, ref: ref || null, rehearsal: Boolean(ref) };
280	}
281	
282	// Run the engine's self-test against the converged tree; green when the machinery
283	// is intact. Same soft shape as runCheckTheWorld — a missing selftest (an older
284	// mount that predates it) is not a failure, it is nothing to run.
285	function runSelfTest(root) {
286	  const st = join(root, '.claudinite/shared/engine/selftest.mjs');
287	  if (!existsSync(st)) return GATE_ABSENT;
288	  try { node([st, '--strict'], { CLAUDE_PROJECT_DIR: root }, { cwd: root }); return gateOutcome(null); }
289	  catch (e) { return gateOutcome(e); }
290	}
