292	// What a gate said, for the LOG — the full text, not a summary. This is the one
293	// place the findings belong: the Action log is an observability surface nothing
294	// reads programmatically, so it carries everything, while the dispatch issue
295	// carries only the condition (preprocess.mjs, the §3 exception).
296	function logGateOutput(label, outcome) {
297	  const body = outcome.output ? `\n${outcome.output}` : ' (no output)';
298	  console.log(`baselining: ${label} ${outcome.crashed ? 'COULD NOT RUN' : `exited ${outcome.status}`} —${body}`);
299	}
