301	// Deliver the converge as one commit on a FRESH per-cycle maintenance branch,
302	// native git: dispose of the family's open PR first (merge it if last cycle's
303	// content is verified, otherwise close it), then cut a new dated branch + PR and
304	// arm auto-merge when the member asked for it.
305	//
306	// Nothing is reused. A maintenance PR is one cycle's deterministic converge, and
307	// a cycle that did not land has nothing to hand the next one — inheriting it is
308	// what turned a single failed arm into a PR that outlived every subsequent cycle
309	// (#455/#205/#95). The disposal happens BEFORE the converge is pushed, because
310	// the push would replace the head sha the merge evidence hangs on.
311	async function deliver(root, repo, base, token, delivery, seed, withheld = []) {
312	  const { json: pulls } = await gh(token, `/repos/${repo}/pulls?state=open&per_page=100`);
313	  const openPr = openMaintenancePull(Array.isArray(pulls) ? pulls : []);
314	  let pr = null;
315	  let merged = false;
316	
317	  if (openPr?.number) {
318	    // `wait` is the one case that keeps the PR: its checks are still running and
319	    // may yet land it. Skip this cycle entirely rather than race them — the
320	    // converge is idempotent, so tomorrow simply does it again.
321	    const kept = await disposeOpenPull(token, repo, openPr, delivery)
322	      .catch((e) => { console.log(`baselining: disposing of PR #${openPr.number} failed: ${e.message}`); return openPr; });
323	    if (kept) {
324	      console.log(`baselining: PR #${openPr.number} still stands — leaving this cycle's converge undelivered`);
325	      // Same shape as the delivery path below — the caller reads `.branch`/`.pr`
326	      // unconditionally, and the bare-ref return this used to make crashed it.
327	      return { branch: kept.head?.ref ?? null, pr: kept.number ?? openPr.number, merged: false };
328	    }
329	  }
330	
331	  const branch = maintenanceBranchName(new Date().toISOString().slice(0, 10), seed);
332	
333	  git(['-C', root, 'checkout', '-B', branch]);
334	  git(['-C', root, 'add', '-A']);
335	  // Withhold what this token cannot push (see withheldWorkflowPaths). Unstaged, not
336	  // reverted: the file stays in the working tree so nothing here has to reason about
337	  // restoring it, and the runner is discarded at job end either way. The agent lands
338	  // them on this same branch afterwards.
339	  for (const p of withheld) git(['-C', root, 'restore', '--staged', p]);
340	  // With everything else staged, a converge whose ONLY content was a workflow file has
341	  // nothing left to commit. It still needs the branch and the PR — that is where the
342	  // agent does its half — so the commit is allowed to be empty rather than skipped.
343	  const staged = git(['-C', root, 'diff', '--cached', '--name-only']).split('\n').filter(Boolean);
344	  const note = withheld.length
345	    ? `\n\nWithheld for the agent stage (the Action token cannot push a workflow file):\n${withheld.map((p) => `- ${p}`).join('\n')}`
346	    : '';
347	  git(['-C', root, '-c', 'user.name=claudinite[bot]', '-c', 'user.email=claudinite@users.noreply.github.com',
348	    'commit', ...(staged.length ? [] : ['--allow-empty']),
349	    '-m', `Claudinite maintenance: converge vendored mount, wiring, and migration notes${note}`]);
350	  const remote = `https://x-access-token:${token}@github.com/${repo}.git`;
351	  git(['-C', root, 'push', '--force', remote, `HEAD:refs/heads/${branch}`]);
352	
353	  const body = delivery === 'auto-merge'
354	    ? 'Automated Claudinite maintenance (deterministic converge + any migration notes). Re-cut each cycle; auto-merges once this repo\'s checks pass.'
355	    : 'Automated Claudinite maintenance (deterministic converge + any migration notes). Re-cut each cycle; left for your review.';
356	  const created = await gh(token, `/repos/${repo}/pulls`, {
357	    method: 'POST', body: { head: branch, base, title: 'Claudinite maintenance', body },
358	  });
359	  const failure = pullCreateError(created.status, created.json);
360	  if (failure) throw new Error(`could not open the maintenance PR for ${branch}: ${failure}`);
361	  pr = created.json;
362	
363	  // Land what was just pushed, per the member's delivery and the repo's own
364	  // shape — the shared helper owns every nuance (land-pr.mjs): it starts the
365	  // PR's checks (#565), reads what the base branch requires, then merges
366	  // directly (no PR CI), verifies-then-lands (ungated base — the arm would be
367	  // rejected "clean status" every cycle, #677), or arms auto-merge with the
368	  // landing poll as fallback (#649). An arm that still could not land costs one
369	  // cycle, not forever: the next cycle merges this PR on its concluded runs
370	  // (pullDisposition) or closes it and re-cuts. Idempotent either way.
371	  if (pr?.number) {
372	    const landed = await landDelivery({
373	      token, repo, base, delivery, pr,
374	      log: (s) => console.log(`baselining: ${s}`),
375	    });
376	    merged = landed.merged;
377	  }
378	  // What this cycle delivered. The scheduler records it in the dispatch issue, which is
379	  // the agent's source for these artifacts.
380	  return { branch, pr: pr?.number ?? null, merged };
381	}
382	
383	// The I/O half of the disposal: read the workflow runs for the open PR's head
384	// sha, decide with pullDisposition, and either merge it (last cycle's content is
385	// verified — the arm just never landed it) or close it and delete its branch so
386	// this cycle re-cuts from scratch. Returns the PR when it still stands (a `wait`,
387	// a `review` member, or a failed attempt), null when the way is clear.
388	//
389	// Best-effort throughout: anything unreadable or unmergeable leaves the PR as it
390	// found it, and the cycle skips rather than piling a second PR on top.
391	async function disposeOpenPull(token, repo, pr, delivery) {
392	  const { status, json } = await gh(token, `/repos/${repo}/actions/runs?head_sha=${pr.head?.sha}&per_page=100`);
393	  if (status !== 200) {
394	    console.log(`baselining: could not read the runs for PR #${pr.number}'s head (HTTP ${status})`);
395	    return pr;
396	  }
397	  const runs = (json?.workflow_runs ?? []).map((r) => ({ name: r.name, status: r.status, conclusion: r.conclusion }));
398	  const disposition = pullDisposition({ delivery, runs });
399	
400	  if (disposition === 'keep' || disposition === 'wait') {
401	    console.log(`baselining: keeping PR #${pr.number} (${disposition})`);
402	    return pr;
403	  }
404	
405	  if (disposition === 'merge') {
406	    const res = await gh(token, `/repos/${repo}/pulls/${pr.number}/merge`, {
407	      method: 'PUT', body: { merge_method: 'squash' },
408	    });
409	    if (res.status === 200) {
410	      console.log(`baselining: merged PR #${pr.number} — ${mergeReason(runs)}`);
411	      await deleteBranch({ token, repo, ref: pr.head?.ref, log: (s) => console.log(`baselining: ${s}`) });
412	      return null;
413	    }
414	    console.log(`baselining: could not merge PR #${pr.number} (${res.status}: ${res.json?.message ?? 'no message'})`
415	      + ' — closing it instead; the converge is idempotent and this cycle re-cuts it');
416	  }
417	
418	  // Closed, not left to rot: whatever went wrong on that head, the next converge
419	  // reproduces the same content from the same inputs. Named in the log because a
420	  // member closing its maintenance PR every single night is a repo whose CI needs
421	  // a human, and the pattern has to be visible to be noticed.
422	  const closed = await gh(token, `/repos/${repo}/pulls/${pr.number}`, { method: 'PATCH', body: { state: 'closed' } });
423	  if (closed.status !== 200) {
424	    console.log(`baselining: could not close PR #${pr.number} (${closed.status}) — leaving it and skipping this cycle`);
425	    return pr;
426	  }
427	  console.log(`baselining: closed PR #${pr.number} — it did not land (${failureSummary(runs)}); re-cutting this cycle`);
428	  await deleteBranch({ token, repo, ref: pr.head?.ref, log: (s) => console.log(`baselining: ${s}`) });
429	  return null;
430	}
431	
432	// Ask the owner to add a repo Actions secret a task declares in `required_secrets`
433	// but the repo has not configured. The wiring converge stamps every declared name
434	// into the scheduler workflow, so by the time this runs the value is either in the
435	// environment or genuinely unset — no separate probe needed.
436	//
437	// This is the adoption interview's posture, not a gate: nothing fails, no check
438	// fires, and the task that needs the secret simply doesn't work until someone adds
439	// it. One open issue per repo (matched by exact title) so an unconfigured secret
440	// costs one issue, not one per night. Exported for the tests.
441	export const SECRETS_ISSUE_TITLE = 'Claudinite: configure required Actions secrets';
442	
443	export function unconfiguredSecrets(declared, env) {
444	  return (declared ?? []).filter((name) => !env[name]);
445	}
446	
447	async function askForSecrets(token, repo, names) {
448	  const q = encodeURIComponent(`repo:${repo} in:title "${SECRETS_ISSUE_TITLE}" state:open`);
449	  const { json } = await gh(token, `/search/issues?q=${q}&per_page=10`);
450	  if ((json?.items ?? []).some((i) => (i.title ?? '').trim() === SECRETS_ISSUE_TITLE)) return false;
451	  const body = [
452	    'A scheduled task in this repo declares a repo **Actions secret** that is not configured yet.',
453	    'Until it is, that task cannot do its work — everything else keeps running normally.',
454	    '',
455	    ...names.map((n) => `- \`${n}\``),
456	    '',
457	    `Add each one at https://github.com/${repo}/settings/secrets/actions, then close this issue.`,
458	  ].join('\n');
459	  await gh(token, `/repos/${repo}/issues`, { method: 'POST', body: { title: SECRETS_ISSUE_TITLE, body } });
460	  return true;
461	}
462	
463	export async function main() {
464	  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
465	  const repo = process.env.CLAUDINITE_REPO || process.env.GITHUB_REPOSITORY;
466	  const base = process.env.CLAUDINITE_DEFAULT_BRANCH || 'main';
467	  const token = process.env.GITHUB_TOKEN;
468	  const requestFile = process.env.CLAUDINITE_REQUEST_AGENT;
469	  // Set by deliver() to `{ branch, pr, merged }`; stays null when this cycle opened
470	  // nothing, which is what the dispatch issue then says.
471	  let delivered = null;
472	  if (!repo) { console.error('baselining: no repo (CLAUDINITE_REPO/GITHUB_REPOSITORY)'); process.exit(1); }
473	  if (!token) { console.error('baselining: no GITHUB_TOKEN in env'); process.exit(1); }
474	
475	  const checksPath = join(root, '.claudinite-checks.json');
476	  if (!existsSync(checksPath)) { console.log('baselining: no .claudinite-checks.json — nothing to self-refresh'); return; }
477	  const priorRaw = JSON.parse(readFileSync(checksPath, 'utf8'));
478	  const priorStamp = priorRaw.claudinite ?? {};
479	  if (!priorStamp.updated && !priorStamp.ref) {
480	    console.log('baselining: no vendored-mount stamp — nothing to self-refresh (canon home or pre-adoption)');
481	    return; // quiet, no agent (matches the precondition self-skip)
482	  }
483	  // A repo the update flows serve is not this mechanism's to converge (#768's skew
484	  // risk). Stepping aside is the FIRST thing after reading the declaration and
485	  // before any clone or write: two mechanisms converging one mount would race on
486	  // the same files, and the loser's write reads as drift the winner then repairs,
487	  // nightly, forever. Quiet and agentless — a repo served elsewhere is not an
488	  // anomaly, so there is nothing here for a human to look at.
489	  //
490	  // A member's copy of this worker is only as new as its last converge, so a repo
491	  // flipped before its mount carries this check keeps baselining for one more
492	  // cycle. That is the safe direction of that lag: it converges twice by the old
493	  // mechanism rather than falling between the two.
494	  const served = servedBy(priorRaw);
495	  if (served.mechanism !== 'baselining') {
496	    console.log(`baselining: this repo is served by the ${served.mechanism} flow — standing down`);
497	    return;
498	  }
499	  if (served.invalid !== undefined) {
500	    console.log(`baselining: maintenance.mechanism "${served.invalid}" is not a mechanism — proceeding as ${served.mechanism}`);
501	  }
502	
503	  const { delivery, materialize } = resolveDelivery(priorRaw?.maintenance?.delivery);
504	  if (!delivery) {
505	    console.error(`baselining: maintenance.delivery "${priorRaw?.maintenance?.delivery}" is neither auto-merge nor review`);
506	    process.exit(1);
507	  }
508	  // Materialize the missing key BEFORE the converge, so the repair rides this
509	  // cycle's maintenance commit like any other converged surface.
510	  if (materialize) {
511	    priorRaw.maintenance = { ...priorRaw.maintenance, delivery };
512	    writeFileSync(checksPath, JSON.stringify(priorRaw, null, 2) + '\n');
513	    console.log(`baselining: maintenance.delivery was missing — materialized "${delivery}"`);
514	  }
515	
516	  // 1. Fetch canon at head as a ROOTLESS tree (drop .git so apply-vendor-set's
517	  //    ancestry guards skip — a shallow clone can't answer them, and it is head
518	  //    by construction).
519	  const source = canonSource(process.env);
520	  const tmp = mkdtempSync(join(tmpdir(), 'claudinite-canon-'));
521	  git(source.ref
522	    ? ['clone', '--depth', '1', '--branch', source.ref, source.url, tmp]
523	    : ['clone', '--depth', '1', source.url, tmp]);
524	  const headSha = git(['-C', tmp, 'rev-parse', 'HEAD']).trim();
525	  rmSync(join(tmp, '.git'), { recursive: true, force: true });
526	  if (source.rehearsal) {
527	    console.log(`baselining: REHEARSAL against ${source.url}@${source.ref} (${headSha.slice(0, 8)}) — `
528	      + 'the stamp will be restored, and nothing is delivered');
529	  }
530	
531	  // 2-4. Deterministic converge: mount + stamp, then wiring, then mechanical notes.
532	  node([join(tmp, 'vendoring/apply-vendor-set.mjs'), '--target', root, '--ref', headSha]);
533	  const wiringOut = node([join(tmp, 'engine/scheduler/converge-wiring.mjs'), repo], { CLAUDINITE_REPO_ROOT: root });
534	  // The handshake (engine/migrations/registry.mjs, WITHHOLD_CAPABLE_ENV): THIS worker withholds
535	  // workflow paths from its commit and hands them to the agent, so a record may safely
536	  // materialize one. An older vendored worker does not set it and the materialization is
537	  // skipped instead of wedging its push. Set here, by the code that does the withholding,
538	  // because the question is what the RUNNING process can do — and the disk cannot answer
539	  // it: apply-vendor-set above has already overwritten this very file with the new
540	  // version while this old-or-new code is the thing actually executing.
541	  const declarationBefore = readFileSync(checksPath, 'utf8');
542	  node([join(tmp, 'engine/migrations/apply.mjs')], { CLAUDE_PROJECT_DIR: root, CLAUDINITE_CAN_WITHHOLD_WORKFLOWS: '1' });
543	  // A note may have DECLARED a pack (the seed shape). The mount above was computed
544	  // from the declaration as it stood a moment ago, so the new pack's content is not
545	  // in it — and a declared pack whose code is absent is a BLOCKING config error until
546	  // something re-converges. Re-run the vendor pass when, and only when, the
547	  // declaration actually changed: it is whole-set convergence over a local tree, so
548	  // the cost is small and the result identical when nothing moved.
549	  if (readFileSync(checksPath, 'utf8') !== declarationBefore) {
550	    console.log('baselining: a migration note changed the declaration — re-converging the mount');
551	    node([join(tmp, 'vendoring/apply-vendor-set.mjs'), '--target', root, '--ref', headSha]);
552	  }
553	
554	  // Ask about any declared secret the repo hasn't configured — but only once the
555	  // wiring is settled. On the cycle that FIRST stamps a name into the workflow the
556	  // value cannot be in this process's env yet, so asking then would nag about a
557	  // secret the owner may well have already added; next cycle tells the truth.
558	  const { declaredSecrets } = await import(pathToFileURL(join(tmp, 'engine/scheduler/converge-wiring.mjs')).href);
559	  const missingSecrets = wiringOut.includes('.github/workflows/claudinite-scheduler.yml')
560	    ? []
561	    : unconfiguredSecrets(await declaredSecrets(root, JSON.parse(readFileSync(checksPath, 'utf8'))), process.env);
562	  if (missingSecrets.length && await askForSecrets(token, repo, missingSecrets)) {
563	    console.log(`baselining: asked the owner to configure ${missingSecrets.join(', ')}`);
564	  }
565	
566	  // 5. Pending agentic notes — selected BY VERSION, and no stamp hold (#768 Phase 4).
567	  //    A note is pending exactly while its record is still in this repo's gap, which
568	  //    is the same predicate vendoring fetches by and checks tolerate by. The date
569	  //    comparison it replaces needed the stamp HELD to keep a note selected, and that
570	  //    hold is what made `claudinite.updated` unreadable as freshness: a healthy repo
571	  //    with outstanding agentic work looked identical to a dead one, which is a
572	  //    mistake made about two live members on 2026-08-12 before the flip.
573	  //
574	  //    Version selection needs no hold: the record leaves the gap when the version
575	  //    that carries its change is installed, and nothing before then can deselect it.
576	  const { loadMigrations, agenticMigrations } = await import(pathToFileURL(join(tmp, 'engine/migrations/registry.mjs')).href);
577	  const { migrationApplies } = await import(pathToFileURL(join(tmp, 'engine/checks/helpers/active-migrations.mjs')).href);
578	  const pending = agenticMigrations(await loadMigrations())
579	    .filter((m) => migrationApplies(m.dir, { installed: priorStamp }))
580	    .sort((a, b) => String(a.landed).localeCompare(String(b.landed)));
581	
582	  // 6. Meaningful change? A stamp-only bump against an unchanged head is not one —
583	  //    revert it and stay quiet (no nightly stamp-only noise).
584	  const changed = git(['-C', root, 'status', '--porcelain'])
585	    .split('\n').map((l) => l.slice(3)).filter(Boolean);
586	  // `materialize` excluded: a materialized delivery key also touches only
587	  // .claudinite-checks.json, and reverting it would re-drift the repo every night
588	  // and never land the repair.
589	  const onlyStamp = changed.length > 0 && !materialize && changed.every((p) => p === '.claudinite-checks.json');
590	  if (onlyStamp && priorStamp.ref === headSha && !pending.length) {
591	    git(['-C', root, 'checkout', '--', '.claudinite-checks.json']);
592	    console.log('baselining: mount already at canon head, nothing changed — agentless, quiet');
593	    return;
594	  }
595	  const meaningfulChange = changed.length > 0;
596	  // What this stage cannot push. Computed here, before the escalation gate, because a
597	  // withheld file is residual work for the agent exactly like a pending agentic note.
598	  const withheld = withheldWorkflowPaths(changed);
599	  if (withheld.length) {
600	    console.log(`baselining: withholding ${withheld.length} workflow file(s) from the push — `
601	      + `the Action token cannot write .github/workflows/; the agent stage lands them: ${withheld.join(', ')}`);
602	  }
603	
604	  // 6b. SELF-TEST the converged tree before judging its content. This asks "can
605	  //     Claudinite still run here?" — mount, stamp, pack manifests, hook targets,
606	  //     mounted skills, cron, migrations registry — and it is the gate that would
607	  //     have caught #555 the night it landed: a required manifest field arrived
608	  //     with no migration, every consumer pack stopped validating, and because a
609	  //     pack that fails validation contributes NO rules, check_the_world went on
610	  //     reporting green about a corpus it was no longer running. A content check
611	  //     cannot see its own machinery break. This runs on the just-converged tree,
612	  //     so it judges what the member is about to live with.
613	  const selftest = runSelfTest(root);
614	  if (!selftest.ok) {
615	    console.log('baselining: the converged mount FAILED its self-test — requesting the agent');
616	    logGateOutput('selftest --strict', selftest);
617	  }
618	
619	  // 7. Escalation gate: run the conformance checks only when a change happened and
620	  //    no agentic note already forces the agent. A failed self-test forces it too:
621	  //    broken machinery is exactly the judgment case, and merging it would spread
622	  //    the breakage to a repo that was working an hour ago.
623	  const checks = (meaningfulChange && !pending.length) ? runCheckTheWorld(root) : GATE_ABSENT;
624	  if (!checks.ok) logGateOutput('check_the_world', checks);
625	  const reason = escalation({
626	    pendingCount: pending.length, meaningfulChange, checksPass: checks.ok, selftestOk: selftest.ok,
627	    withheldCount: withheld.length, checksCrashed: checks.crashed, selftestCrashed: selftest.crashed,
628	  });
629	  const requestAgent = reason !== null;
630	
631	  // 7b. A REHEARSAL stops here. It has done the only thing it was for — converged
632	  //     this real repo against a canon BRANCH and asked whether the result still
633	  //     works — and now it must leave no trace: no commit, no branch, no PR, and
634	  //     above all no stamp. Stamping a branch head would leave the member
635	  //     `ref-not-on-trunk`, which the #328 anti-rewind guard then refuses to
636	  //     converge over: a rehearsal that wedged the repo it was rehearsing on.
637	  //     `git checkout -- .` restores the working tree wholesale, so the mount goes
638	  //     back to the vendored snapshot the repo actually runs.
639	  if (source.rehearsal) {
640	    git(['-C', root, 'checkout', '--', '.']);
641	    const verdict = selftest.ok && checks.ok ? 'PASS' : 'FAIL';
642	    console.log(`baselining: rehearsal ${verdict} — selftest ${selftest.ok ? 'ok' : 'FAILED'}, `
643	      + `checks ${checks.ok ? 'green' : 'RED'}, ${changed.length} file(s) would have changed. Working tree restored.`);
644	    if (verdict === 'FAIL') process.exit(1);   // the canary's whole purpose: fail the canon PR
645	    return;
646	  }
647	
648	  // 8. Deliver the converge (only when there's something to land).
649	  if (meaningfulChange || pending.length) {
650	    const seed = Math.random().toString(36).slice(2, 8);
651	    delivered = await deliver(root, repo, base, token, delivery, seed, withheld);
652	    console.log(`baselining: delivered converge on ${delivered.branch}${delivered.pr ? ` (PR #${delivered.pr}${delivered.merged ? ', merged' : ''})` : ''} (${delivery})`);
653	  } else {
654	    console.log('baselining: no change to deliver');
655	  }
656	
657	  // 9. Request the agent only when judgment is left (conditional handoff, §3) — naming
658	  //    what this run created AND why the agent is being woken. `delivered` stays null
659	  //    when nothing was opened, and the issue then names nothing; `reason` is non-null
660	  //    exactly when the agent is requested at all.
661	  if (requestAgent && requestFile) {
662	    writeFileSync(requestFile, `${JSON.stringify({ marker: AGENT_REQUEST_MARKER, delivered, reason })}\n`);
663	  }
664	  console.log(requestAgent
665	    ? `baselining: requested agent stage (${reason.code}: ${reason.detail})`
666	    : 'baselining: agentless night — deterministic converge delivered, no agent needed');
667	}
668	
669	// Run only when invoked directly (the scheduler's `node worker.mjs`), never on
670	// import — a test imports the pure helpers without any git or network.
671	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
672	  main().catch((e) => { console.error(`baselining preprocessing failed: ${e.message}`); process.exit(1); });
673	}
674

